"""Qualify six full-size direct-memo lifecycle runs before freezing the timing runtime.

The original harness emits timing fields, which are preserved but not summarized
or pooled. Only result, route, configuration, cleanup, and owner mapping qualify.
"""
import argparse
import importlib.util
import json
import os
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
BUILDER = HERE.parent / 'contracts/compile_freeze_direct_runtime.py'
DRIVER = HERE / 'run-comparison.py'
SCHEDULE = [(fixture, arm) for fixture in ('fanout', 'shared-tail')
            for arm in ('ordinary', 'dense', 'direct')]


def load_module(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    return module


def modules():
    if str(HERE) not in sys.path:
        sys.path.insert(0, str(HERE))
    return load_module('direct_memo_timing', DRIVER), load_module('direct_memo_builder', BUILDER)


def command_for(driver, runtime, folder, fixture, arm):
    properties = driver.arm_properties({}, fixture, arm)
    return [driver.JAVA, *driver.JVM, *['-D' + key + '=' + value for key, value in properties.items()],
        '-cp', runtime['classpath'], driver.QUALIFIED_LAUNCHER, fixture, '--arm=' + arm,
        '--source=' + runtime['descriptor']['sourceIdentity'], '--warmup=8', '--iterations=5',
        *driver.FIXTURES[fixture]['arguments'], '--consumption=full', '--output=' + str(folder / 'samples.jsonl'),
        '--store=' + str(folder / 'store')]


def folder_for(output, ordinal, fixture, arm):
    return output / f'{ordinal:02d}-{fixture}-{arm}'


def plan_for(driver, runtime, output):
    identity = driver.identity
    return {'format': 1, 'scope': driver.ACCOUNTING_SCOPE,
        'purpose': 'Full-size result, route, owner/query mapping, and cleanup preflight; timings not analyzed or pooled.',
        'runtimeFolder': str(runtime['folder']),
        'compileReceiptFile': str(runtime['folder'] / 'compile-receipt.json'),
        'compileReceiptFileSha256': identity.sha(runtime['folder'] / 'compile-receipt.json'),
        'sourceIdentity': runtime['descriptor']['sourceIdentity'],
        'runtimeManifest': runtime['manifest'], 'prefixFiles': runtime['prefixFiles'],
        'tools': {str(path): identity.sha(path) for path in
                  (Path(__file__), DRIVER, BUILDER, HERE / 'runtime_identity.py')},
        'schedule': [{'ordinal': i, 'fixture': fixture, 'arm': arm,
                      'command': command_for(driver, runtime, folder_for(output, i, fixture, arm), fixture, arm)}
                     for i, (fixture, arm) in enumerate(SCHEDULE)],
        'warmupsPerJvm': 8, 'measurementsPerJvm': 5, 'freshJvms': 6, 'queries': 78,
        'directMemoOwners': 26, 'ordinaryAndDenseMemoOwners': 0, 'timeoutSeconds': 300,
        'configuration': driver.CONFIGURATION, 'memoPolicy': driver.MEMO_POLICY,
        'statisticsPolicy': driver.ACCOUNTING_POLICY,
        'failurePolicy': 'Stop without replacements; preserve every output. No timing-based selection.'}


def qualify_lifecycle(runtime_folder, lifecycle_output, write_receipt=False):
    """Replay the complete raw preflight. The compiler/freezer calls this without Java."""
    driver, builder = modules()
    identity, check = driver.identity, driver.check
    runtime = builder.compiled_runtime(Path(runtime_folder))
    runtime['overlayClassFiles'] = runtime['prefixFiles']
    output = Path(lifecycle_output).resolve(strict=True)
    plan_path = output / 'preflight-protocol.json'
    check(json.loads(plan_path.read_text()) == plan_for(driver, runtime, output),
          'Lifecycle plan, tool hashes, runtime, or command schedule changed')
    expected_dirs = {folder_for(output, i, fixture, arm).name for i, (fixture, arm) in enumerate(SCHEDULE)}
    check({p.name for p in output.iterdir() if p.is_dir()} == expected_dirs,
          'Missing or additional preflight fork directory')
    files = {str(plan_path): identity.sha(plan_path)}
    runs, normalized_metadata, measured_routes = [], {}, {}
    previous_end = None
    for ordinal, (fixture, arm) in enumerate(SCHEDULE):
        folder = folder_for(output, ordinal, fixture, arm)
        command = json.loads((folder / 'command.json').read_text())
        process = json.loads((folder / 'process-result.json').read_text())
        check(command['argv'] == command_for(driver, runtime, folder, fixture, arm)
              and command['cwd'] == str(ROOT), 'Preflight command differs from the full-size frozen fixture')
        check(process['exitCode'] == 0 and process['failure'] is None
              and process['startedEpochNs'] == command['startedEpochNs']
              and process['finishedEpochNs'] >= process['startedEpochNs']
              and (previous_end is None or process['startedEpochNs'] >= previous_end),
              'Preflight process failed or overlapped')
        previous_end = process['finishedEpochNs']
        metadata, samples, audit, measured, validation, accounting = driver.validate_run(
            folder, fixture, arm, runtime, {}, write_validation=False)
        check(validation['targetQualified'], 'Preflight actual route/tier does not qualify')
        normalized = driver.normalized_metadata(metadata)
        routes = driver.route_histogram(measured)
        if fixture not in normalized_metadata:
            normalized_metadata[fixture], measured_routes[fixture] = normalized, routes
        check(normalized == normalized_metadata[fixture] and routes == measured_routes[fixture],
              'Preflight configuration or measured route histogram differs across treatments')
        runs.append({'round': 0, 'fixture': fixture, 'arm': arm, 'samples': samples,
                     'accounting': accounting, 'rootAudit': audit})
        for name in ('command.json', 'process-result.json', 'samples.jsonl', 'root-host-audit.json',
                     'direct-memo-statistics.jsonl', 'console.log'):
            path = folder / name
            files[str(path)] = identity.sha(path)
    indexed = {(run['fixture'], run['arm']): run for run in runs}
    pairs = []
    for fixture in ('fanout', 'shared-tail'):
        for comparator in ('ordinary', 'dense'):
            audit = driver.treatment_pair_audit(indexed[fixture, comparator], indexed[fixture, 'direct'])
            check(audit['passed'], 'Preflight per-query route/tier or adjacency observations differ')
            pairs.append({'fixture': fixture, 'comparator': comparator, 'queryPairs': len(audit['queries']),
                          'matched': True, 'rawResolverEqualityRequired': False})
    check(sum(len(run['samples']) for run in runs) == 78
          and sum(len(run['accounting']['owners']) for run in runs) == 26,
          'Preflight query or direct owner count changed')
    check(all(identity.sha(path) == digest for path, digest in files.items()),
          'A raw preflight file changed during validation')
    # Recheck complete byte identity only after every process has ended.
    after = builder.compiled_runtime(Path(runtime_folder))
    check(after['manifest'] == runtime['manifest'] and after['prefixFiles'] == runtime['prefixFiles'],
          'Preflight runtime changed')
    receipt = {'format': 1, 'scope': driver.ACCOUNTING_SCOPE, 'qualified': True,
        'runtimeFolder': str(runtime['folder']), 'sourceIdentity': runtime['descriptor']['sourceIdentity'],
        'compileReceiptFile': str(runtime['folder'] / 'compile-receipt.json'),
        'compileReceiptFileSha256': identity.sha(runtime['folder'] / 'compile-receipt.json'),
        'freshJvms': 6, 'queries': 78, 'directMemoOwners': 26, 'ordinaryAndDenseMemoOwners': 0,
        'perFixture': [{'fixture': fixture, 'arms': ['ordinary', 'dense', 'direct'], 'queries': 39,
                       'directMemoOwners': 13} for fixture in ('fanout', 'shared-tail')],
        'routeAndAdjacencyPairs': pairs, 'rawFiles': files,
        'timingAnalysisPerformed': False, 'pooledIntoMainComparison': False,
        'qualifiedForTimingRuntimeFreeze': True}
    if write_receipt:
        path = output / 'validation-receipt.json'
        if path.exists():
            check(json.loads(path.read_text()) == receipt, 'Existing lifecycle receipt differs from raw replay')
        else:
            identity.write_new(path, receipt)
    return receipt


def launch(args):
    driver, builder = modules()
    check, identity = driver.check, driver.identity
    check(args.slot_released, 'Full-size lifecycle launch needs the exclusive Java slot')
    for key in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS'):
        check(not os.environ.get(key), 'Unexpected JVM environment: ' + key)
    runtime = builder.compiled_runtime(args.runtime)
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    identity.write_new(output / 'preflight-protocol.json', plan_for(driver, runtime, output))
    try:
        for ordinal, (fixture, arm) in enumerate(SCHEDULE):
            folder = folder_for(output, ordinal, fixture, arm)
            folder.mkdir()
            check(identity.tree_files(runtime['manifest'][0]['path']) == runtime['prefixFiles'],
                  'Experimental prefix changed before lifecycle fork')
            print(f'Lifecycle {ordinal + 1}/6: {fixture}, {arm}; timing fields will not be analyzed', flush=True)
            driver.run_fork(command_for(driver, runtime, folder, fixture, arm), folder, 300)
            _, _, _, _, validation, _ = driver.validate_run(
                folder, fixture, arm, runtime, {}, write_validation=False)
            check(validation['targetQualified'], 'Lifecycle fork did not qualify its actual route')
        receipt = qualify_lifecycle(args.runtime, output, write_receipt=True)
        print(json.dumps({'qualified': receipt['qualified'], 'freshJvms': 6, 'queries': 78,
                          'validationReceipt': str(output / 'validation-receipt.json')}))
    except BaseException as error:
        identity.write_new(output / 'lifecycle-failure.json', {'qualified': False,
            'exception': type(error).__name__, 'message': str(error),
            'preserved': True, 'replacementAllowed': False, 'acceptedTimingEstimates': False})
        raise


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--runtime', type=Path, required=True, help='Compiled runtime directory, before descriptor freeze')
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--qualify-only', action='store_true', help='Replay existing raw files without launching Java')
    parser.add_argument('--slot-released', action='store_true')
    args = parser.parse_args()
    if args.qualify_only:
        receipt = qualify_lifecycle(args.runtime, args.output, write_receipt=True)
        print(json.dumps({'qualified': receipt['qualified'], 'jvmsLaunched': 0, 'queries': receipt['queries']}))
    else:
        launch(args)


if __name__ == '__main__':
    main()
